    29  #define MAX_ITERATIONS 100
    30
    31  #include <stdlib.h>
    32  #include <string.h>
    33
    34  #include <openthread/instance.h>
    35  #include <openthread/ip6.h>
    36  #include <openthread/link.h>
    37  #include <openthread/tasklet.h>
    38  #include <openthread/thread.h>
    39  #include <openthread/thread_ftd.h>
    40  #include <openthread/platform/radio.h>
    41
    42  #include "fuzzer_platform.h"
    43  #include "common/code_utils.hpp"
    44
    45  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    46  {
    47      const otPanId panId = 0xdead;
    48
    49      otInstance * instance = NULL;
    50      otRadioFrame frame;
    51      uint8_t *    buf = NULL;
    52
    53      VerifyOrExit(size <= OT_RADIO_FRAME_MAX_SIZE);
    54
    55      FuzzerPlatformInit();
    56
    57      instance = otInstanceInitSingle();
    58      otLinkSetPanId(instance, panId);
    59      otIp6SetEnabled(instance, true);
    60      otThreadSetEnabled(instance, true);
    61      otThreadBecomeLeader(instance);
    62
    63      buf = static_cast<uint8_t *>(malloc(size));
    64
    65      memset(&frame, 0, sizeof(frame));
    66      frame.mPsdu    = buf;
    67      frame.mChannel = 11;
    68      frame.mLength  = static_cast<uint8_t>(size);
    69
    70      memcpy(buf, data, frame.mLength);
    71
    72      otPlatRadioReceiveDone(instance, &frame, OT_ERROR_NONE);
    73
    74      VerifyOrExit(!FuzzerPlatformResetWasRequested());
    75
    76      for (int i = 0; i < MAX_ITERATIONS; i++)
    77      {
    78          while (otTaskletsArePending(instance))
    79          {
    80              otTaskletsProcess(instance);
    81          }
    82
    83          FuzzerPlatformProcess(instance);
    84      }
    85
    86  exit:
    87
    88      if (buf != NULL)
    89      {
    90          free(buf);
    91      }
    92
    93      if (instance != NULL)
    94      {
    95          otInstanceFinalize(instance);
    96      }
    97
    98      return 0;
    99  }
